CREATE TABLE IF NOT EXISTS "response_cache" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "cache_key" TEXT NOT NULL, "model" TEXT NOT NULL, "response_body" TEXT NOT NULL, "is_stream" BOOLEAN NOT NULL DEFAULT false, "prompt_tokens" INTEGER DEFAULT 0, "completion_tokens" INTEGER DEFAULT 0, "estimated_cost" DOUBLE PRECISION DEFAULT 0, "hit_count" INTEGER NOT NULL DEFAULT 0, "created_at" TEXT NOT NULL, "expires_at" TEXT NOT NULL);
CREATE UNIQUE INDEX "response_cache_key_idx" ON "response_cache" ("cache_key");
CREATE INDEX "response_cache_expires_at_idx" ON "response_cache" ("expires_at");
CREATE INDEX "response_cache_model_idx" ON "response_cache" ("model");
